import java.util.Scanner;

class Majalah {
    String judul;
    int edisi;
    boolean tersedia = true;

    void tampilkan() {
        // Cetak: <judul> - edisi <edisi> [tersedia] atau [dipinjam]. Pakai operator ?: seperti di buku.
    }

    void pinjam() {
        // Bila tersedia: ubah jadi false dan cetak "Dipinjam: <judul>". Bila tidak: cetak "Ditolak, sudah dipinjam: <judul>".
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Majalah m = new Majalah();
        m.judul = in.nextLine();
        m.edisi = Integer.parseInt(in.nextLine().trim());
        int percobaan = Integer.parseInt(in.nextLine().trim());
        m.tampilkan();
        for (int i = 0; i < percobaan; i++) {
            m.pinjam();
        }
        m.tampilkan();
    }
}
